  }),[prospects,comSearch,comFilterStage]);
  const byStage=useMemo(()=>Object.fromEntries(STAGES.map(s=>[s,filteredProspects.filter(r=>r.stage===s)])),[filteredProspects]);
  const comStats=useMemo(()=>({
    total:prospects.length,
